import {ulid} from "ulid";
import _ from "lodash";

export enum FloatSidePattern {
    // 默认不贴边，跟随手指移动
    DEFAULT = 'DEFAULT',
    // 左、右、上、下四个方向固定（一直吸附在该方向边缘，只能在该方向的边缘移动）
    LEFT = 'LEFT',
    RIGHT = 'RIGHT',
    TOP = 'TOP',
    BOTTOM = 'BOTTOM',
    // 根据手指到屏幕边缘的距离，自动选择水平方向的贴边、垂直方向的贴边、四方向的贴边
    AUTO_HORIZONTAL = 'AUTO_HORIZONTAL',
    AUTO_VERTICAL = 'AUTO_VERTICAL',
    AUTO_SIDE = 'AUTO_SIDE',
    // 拖拽时跟随手指移动，结束时贴边
    RESULT_LEFT = 'RESULT_LEFT',
    RESULT_RIGHT = 'RESULT_RIGHT',
    RESULT_TOP = 'RESULT_TOP',
    RESULT_BOTTOM = 'RESULT_BOTTOM',
    RESULT_HORIZONTAL = 'RESULT_HORIZONTAL',
    RESULT_VERTICAL = 'RESULT_VERTICAL',
    RESULT_SIDE = 'RESULT_SIDE'
}
export type WebViewJsParams = {
    fitContentWidth?:true,
    fitContentHeight?:true,
    javaToJsDataString?:string//``
}

export type WebViewConf = {
    backgroundColor?:0
}


export type HtmlConf = {
    url?:string,
    webViewJsParams?:WebViewJsParams,
    webViewConf?:WebViewConf,
    jsBridgeName?:string//"android",
    webViewJsName?:string//"AutoWebViewJs",
    extra?:{
        // javaRunnerId:javaRunner.id,
    }
}
export interface FloatConf {
    /** 位置保存名称，例如 "${positionSaveName}" */
    positionSaveName?: string;
    
    /** 是否可拖拽 */
    draggable?: boolean;
    
    /** 默认 X 坐标 */
    defaultX?: number;  // 对应 Int，使用 number 表示整数
    
    /** 默认 Y 坐标 */
    defaultY?: number;  // 对应 Int，使用 number 表示整数
    
    /** 重置 X 坐标，可选 */
    resetX?: number ;  // 对应 Int?，使用 number | null 表示可空整数
    
    /** 重置 Y 坐标，可选 */
    resetY?: number ;  // 对应 Int?，使用 number | null 表示可空整数
    
    /** 标签，可选 */
    tag?: string ;

    sidePattern?:FloatSidePattern; // default is DEFAULT
}

export type FloatWindowConf = {
    floatConf?:FloatConf
    
    /** 长按退出窗口，外部 URL 打开的 HTML 没有退出方法，用这个来退出。默认 true */
    exitByLongTouch?: number;
}

export type WindowConf = {
    contentType?:string//"html",
    windowType?:string //"float",
    htmlConf?:HtmlConf,
    floatWindowConf?:FloatWindowConf,
    windowId?:string// ulid()
}


export const webViewJsParams:WebViewJsParams = {
    fitContentWidth:true,
    fitContentHeight:true,
    javaToJsDataString:``
}

export const webViewConf:WebViewConf = {
    backgroundColor:0
}

export const htmlConf:HtmlConf = {
    url:``,
    webViewJsParams:webViewJsParams,
    webViewConf:webViewConf,
    jsBridgeName:"android",
    webViewJsName:"AutoWebViewJs",
    extra:{
        // javaRunnerId:javaRunner.id,
    }
}

export const floatConf:FloatConf = {
    positionSaveName:"${positionSaveName}",
    draggable:true
}
export const floatWindowConf:FloatWindowConf = {
    floatConf:floatConf
}

export const windowConf:WindowConf = {
    contentType:"html",
    windowType:"float",
    htmlConf:htmlConf,
    floatWindowConf:floatWindowConf,
    windowId:ulid()
}

export function createWindowConfCopy(conf:any){
    return _.merge({}, windowConf, conf);
}